import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import store, { $storex } from '.'
import { v4 as uuidv4 } from 'uuid'

export const namespaced = true

export const state = () => ({
  // Map of projectId -> activeBoard
  activeBoardByProject: {},
  // Map of projectId -> kanban state
  kanbanByProject: {}
})

export const gettersImpl = getterTree(state, {
  /**
   * Get kanban state for a project
   */
  getProjectKanban: (state) => (projectId) => {
    return state.kanbanByProject[projectId] || { boards: {} }
  },

  /**
   * Get active board ID for a project
   */
  getActiveBoard: (state) => (projectId) => {
    return state.activeBoardByProject[projectId] || null
  },

  /**
   * Get specific board from project kanban
   */
  getBoard: (state) => (projectId, boardTitle) => {
    const kanban = state.kanbanByProject[projectId] || { boards: {} }
    return kanban.boards[boardTitle] || null
  },

  /**
   * Get all boards for a project (with id/title)
   */
  getBoardsList: (state) => (projectId) => {
    const kanban = state.kanbanByProject[projectId] || { boards: {} }
    return Object.entries(kanban.boards).map(([title, data]) => ({
      title,
      id: title,
      ...data
    }))
  },

  /**
   * Get parent boards (no parent_id)
   */
  getParentBoards: (state) => (projectId) => {
    const kanban = state.kanbanByProject[projectId] || { boards: {} }
    return Object.entries(kanban.boards)
      .filter(([_, board]) => !board.parent_id)
      .map(([title, data]) => ({ title, id: title, ...data }))
  },

  /**
   * Get child boards for a specific board
   */
  getChildBoards: (state) => (projectId, boardId) => {
    const kanban = state.kanbanByProject[projectId] || { boards: {} }
    return Object.entries(kanban.boards)
      .filter(([_, board]) => board.parent_id === boardId)
      .map(([title, data]) => ({ title, id: title, ...data }))
  },

  /**
   * Get all descendants of a board (recursive)
   */
  getDescendantBoards: (state) => (projectId, boardId) => {
    const kanban = state.kanbanByProject[projectId] || { boards: {} }
    const descendants = []
    const collect = (parentId) => {
      Object.entries(kanban.boards).forEach(([title, board]) => {
        if (board.parent_id === parentId) {
          descendants.push({ title, id: title, ...board })
          collect(title)
        }
      })
    }
    collect(boardId)
    return descendants
  },

  /**
   * Get columns for a board
   */
  getBoardColumns: (state) => (projectId, boardTitle) => {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    return board?.columns || []
  },

  /**
   * Get all column titles for a board (from columns + task columns)
   */
  getColumnTitles: (state) => (projectId, boardTitle) => {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    return board?.columns?.map(c => c.title) || []
  }
})

export const mutationsImpl = mutationTree(state, {
  /**
   * Initialize kanban for a project
   */
  INIT_PROJECT_KANBAN(state, { projectId, kanbanState = { boards: {} } }) {
    state.kanbanByProject[projectId] = kanbanState
    if (!state.activeBoardByProject[projectId]) {
      const firstBoard = Object.keys(kanbanState.boards)[0]
      state.activeBoardByProject[projectId] = firstBoard || null
    }
  },

  /**
   * Set active board for a project
   */
  SET_ACTIVE_BOARD(state, { projectId, boardTitle }) {
    state.activeBoardByProject[projectId] = boardTitle
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (board) {
      // Mark as active
      Object.values(state.kanbanByProject[projectId].boards).forEach(b => {
        b.active = b === board
      })
      board.last_update = new Date().toISOString()
    }
  },

  /**
   * Create a new board
   */
  CREATE_BOARD(state, { projectId, title, description = '', background = '', parentId = null }) {
    const kanban = state.kanbanByProject[projectId]
    if (!kanban) {
      console.error(`Kanban not initialized for project ${projectId}`)
      return
    }

    if (kanban.boards[title]) {
      console.warn(`Board "${title}" already exists`)
      return
    }

    const newBoard = {
      title,
      description,
      background,
      parent_id: parentId,
      columns: [],
      last_update: new Date().toISOString(),
      created_at: new Date().toISOString(),
      active: false,
      bookmark: false
    }

    kanban.boards[title] = newBoard
  },

  /**
   * Update board properties
   */
  UPDATE_BOARD(state, { projectId, boardTitle, updates }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (!board) {
      console.error(`Board "${boardTitle}" not found`)
      return
    }

    Object.assign(board, updates, { last_update: new Date().toISOString() })
  },

  /**
   * Rename a board
   */
  RENAME_BOARD(state, { projectId, oldTitle, newTitle }) {
    const kanban = state.kanbanByProject[projectId]
    if (!kanban) return

    const board = kanban.boards[oldTitle]
    if (!board) {
      console.error(`Board "${oldTitle}" not found`)
      return
    }

    if (kanban.boards[newTitle]) {
      console.warn(`Board "${newTitle}" already exists`)
      return
    }

    // Update children's parent_id
    Object.values(kanban.boards).forEach(b => {
      if (b.parent_id === oldTitle) {
        b.parent_id = newTitle
      }
    })

    // Move board
    board.title = newTitle
    kanban.boards[newTitle] = board
    delete kanban.boards[oldTitle]

    // Update active board if needed
    if (state.activeBoardByProject[projectId] === oldTitle) {
      state.activeBoardByProject[projectId] = newTitle
    }
  },

  /**
   * Delete a board and its children
   */
  DELETE_BOARD(state, { projectId, boardTitle }) {
    const kanban = state.kanbanByProject[projectId]
    if (!kanban) return

    if (!kanban.boards[boardTitle]) {
      console.error(`Board "${boardTitle}" not found`)
      return
    }

    // Recursively delete children
    const children = Object.keys(kanban.boards).filter(
      title => kanban.boards[title].parent_id === boardTitle
    )
    children.forEach(childTitle => {
      this.DELETE_BOARD(state, { projectId, boardTitle: childTitle })
    })

    // Delete board
    delete kanban.boards[boardTitle]

    // Reset active board if needed
    if (state.activeBoardByProject[projectId] === boardTitle) {
      const remaining = Object.keys(kanban.boards)[0]
      state.activeBoardByProject[projectId] = remaining || null
    }
  },

  /**
   * Toggle board bookmark
   */
  TOGGLE_BOOKMARK(state, { projectId, boardTitle }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (board) {
      board.bookmark = !board.bookmark
      board.last_update = new Date().toISOString()
    }
  },

  /**
   * Add a column to a board
   */
  ADD_COLUMN(state, { projectId, boardTitle, title, color = null, colProjectId = null }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (!board) {
      console.error(`Board "${boardTitle}" not found`)
      return
    }

    if (!board.columns) board.columns = []

    // Check for duplicate
    if (board.columns.some(c => c.title === title)) {
      console.warn(`Column "${title}" already exists`)
      return
    }

    const newColumn = {
      id: uuidv4(),
      title,
      color,
      project_id: colProjectId,
      showSubTasks: false,
      chats: []
    }

    board.columns.push(newColumn)
    board.last_update = new Date().toISOString()
  },

  /**
   * Update column properties
   */
  UPDATE_COLUMN(state, { projectId, boardTitle, columnId, updates }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (!board) return

    const column = board.columns?.find(c => c.id === columnId || c.title === updates.title)
    if (!column) {
      console.error(`Column not found`)
      return
    }

    Object.assign(column, updates)
    board.last_update = new Date().toISOString()
  },

  /**
   * Delete a column from a board
   */
  DELETE_COLUMN(state, { projectId, boardTitle, columnTitle }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (!board) return

    const initialLength = board.columns?.length || 0
    board.columns = board.columns?.filter(c => c.title !== columnTitle) || []

    if (board.columns.length < initialLength) {
      board.last_update = new Date().toISOString()
    }
  },

  /**
   * Reorder columns
   */
  REORDER_COLUMNS(state, { projectId, boardTitle, columnOrder }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (!board || !board.columns) return

    const newColumns = []
    columnOrder.forEach(title => {
      const col = board.columns.find(c => c.title === title)
      if (col) newColumns.push(col)
    })

    board.columns = newColumns
    board.last_update = new Date().toISOString()
  },

  /**
   * Add files to board
   */
  ADD_FILES_TO_BOARD(state, { projectId, boardTitle, filePaths }) {
    const board = state.kanbanByProject[projectId]?.boards[boardTitle]
    if (!board) return

    if (!board.file_list) board.file_list = []
    board.file_list = [...new Set([...board.file_list, ...filePaths])]
    board.last_update = new Date().toISOString()
  }
})

export const actionsImpl = actionTree(
  { state, gettersImpl, mutationsImpl },
  {
    /**
     * Initialize kanban for a project
     */
    async initProjectKanban({ commit }, { projectId, kanbanState = { boards: {} } }) {
      commit('INIT_PROJECT_KANBAN', { projectId, kanbanState })
    },

    /**
     * Set active board for a project
     */
    async setActiveBoard({ commit }, { projectId, boardTitle }) {
      commit('SET_ACTIVE_BOARD', { projectId, boardTitle })
    },

    /**
     * Create a new board
     */
    async createBoard({ commit }, { projectId, title, description = '', background = '', parentId = null }) {
      commit('CREATE_BOARD', { projectId, title, description, background, parentId })
    },

    /**
     * Update board properties
     */
    async updateBoard({ commit }, { projectId, boardTitle, updates }) {
      commit('UPDATE_BOARD', { projectId, boardTitle, updates })
    },

    /**
     * Rename a board
     */
    async renameBoard({ commit }, { projectId, oldTitle, newTitle }) {
      commit('RENAME_BOARD', { projectId, oldTitle, newTitle })
    },

    /**
     * Delete a board and its children
     */
    async deleteBoard({ commit }, { projectId, boardTitle }) {
      commit('DELETE_BOARD', { projectId, boardTitle })
    },

    /**
     * Toggle board bookmark
     */
    async toggleBookmark({ commit }, { projectId, boardTitle }) {
      commit('TOGGLE_BOOKMARK', { projectId, boardTitle })
    },

    /**
     * Add a column to a board
     */
    async addColumn({ commit }, { projectId, boardTitle, title, color = null, colProjectId = null }) {
      commit('ADD_COLUMN', { projectId, boardTitle, title, color, colProjectId })
    },

    /**
     * Update column properties
     */
    async updateColumn({ commit }, { projectId, boardTitle, columnId, updates }) {
      commit('UPDATE_COLUMN', { projectId, boardTitle, columnId, updates })
    },

    /**
     * Delete a column from a board
     */
    async deleteColumn({ commit }, { projectId, boardTitle, columnTitle }) {
      commit('DELETE_COLUMN', { projectId, boardTitle, columnTitle })
    },

    /**
     * Reorder columns
     */
    async reorderColumns({ commit }, { projectId, boardTitle, columnOrder }) {
      commit('REORDER_COLUMNS', { projectId, boardTitle, columnOrder })
    },

    /**
     * Add files to board
     */
    async addFilesToBoard({ commit }, { projectId, boardTitle, filePaths }) {
      commit('ADD_FILES_TO_BOARD', { projectId, boardTitle, filePaths })
    },

    /**
     * Get all boards as flat list with hierarchy info
     */
    getAllBoardsFlat({ getters }, projectId) {
      const kanban = getters.getProjectKanban(projectId)
      return Object.entries(kanban.boards).map(([title, board]) => ({
        title,
        id: title,
        ...board,
        depth: this.calculateBoardDepth(projectId, title)
      }))
    },

    /**
     * Calculate board depth in hierarchy
     */
    calculateBoardDepth({ getters }, { projectId, boardTitle, visited = new Set() }) {
      if (visited.has(boardTitle)) return 0
      visited.add(boardTitle)

      const board = getters.getBoard(projectId, boardTitle)
      if (!board?.parent_id) return 0

      return 1 + this.calculateBoardDepth(projectId, { projectId, boardTitle: board.parent_id, visited })
    }
  }
)

export const getters = gettersImpl
export const mutations = mutationsImpl
export const actions = actionsImpl
